from fractions import Fraction as F
from math import comb
from itertools import product,permutations
import sympy as S
from .authoring import maker,finish
from .common import section
q=maker('probability-states',['conditional sample spaces','state recurrences','indicator expectation'])
p=[
q(1,r'Three balls are drawn uniformly without replacement from five red and four blue balls. What is the probability of exactly two red balls?',F(10,21),[(F(100,243),'Treat the draws as independent with replacement: 3(5/9)²(4/9).'),(F(5,14),'Count one red instead of two.'),(F(20,21),'Order the red choices but not the denominator.'),(F(5,21),'Miss one factor of two in choosing the red pair.')],[r'The equally likely outcomes are three-element subsets of nine distinct balls, counted by C(9,3)=84.',r'The favorable count is C(5,2)C(4,1)=40.',r'The ratio is 40/84=10/21. Color patterns alone are not equally likely outcomes.'],['Use subsets of distinct balls as the uniform sample space.','Choose the two red balls and the one blue ball independently.'],'Match numerator and denominator to the same unordered sample space.',lambda:F(sum(sum(i<5 for i in t)==2 for t in __import__('itertools').combinations(range(9),3)),comb(9,3)),level=2,suffix='-choices-v2'),
q(2,r'Two fair dice are rolled. Given that at least one shows 6, what is the probability their sum is 8?',F(2,11),[(F(1,18),'Use the original sample space after conditioning.'),(F(1,6),'Double-count the outcome (6,6) in the denominator.'),(F(1,11),'Count only one order of (2,6).'),(F(5,36),'Use the unconditional sum-eight probability.')],[r'The conditioned sample space has 6+6-1=11 ordered outcomes.',r'Only (2,6) and (6,2) have sum eight.',r'The probability is 2/11. The condition changes the denominator.'],['List the outcomes retained by the given event.','The double-six outcome belongs to both row and column.'],'Rebuild the sample space under conditioning.',lambda:F(sum(a+b==8 for a,b in product(range(1,7),repeat=2) if a==6 or b==6),sum(a==6 or b==6 for a,b in product(range(1,7),repeat=2))),level=2),
q(3,r'Three fair coins are tossed. Given at least one head, what is the probability of exactly two heads?',F(3,7),[(F(3,8),'Use the unconditional denominator.'),(F(1,2),'Assume conditioning leaves head-count symmetry unchanged.'),(F(2,7),'Confuse the number of heads with the number of outcomes.'),(F(6,7),'Count both orders of indistinguishable head choices.')],[r'The condition excludes only TTT, leaving seven equally likely ordered strings.',r'The exactly-two-head strings are HHT,HTH,THH.',r'The ratio is 3/7.'],['Remove the single forbidden string from the original sample space.','Count strings rather than possible numbers of heads.'],'Condition a uniform string model.',lambda:F(sum(sum(t)==2 for t in product([0,1],repeat=3)),7),level=2),
q(4,r'A fair die is rolled until the first 6. What is the probability that this first 6 occurs on an odd-numbered roll?',F(6,11),[(F(1,2),'Assume odd and even stopping times are equally likely.'),(F(1,6),'Count only the first roll.'),(F(5,11),'Report the probability of an even stopping time.'),(F(5,6),'Report the probability of failing once.')],[r'Let p be the desired probability from a fresh start.',r'A six on the first roll succeeds with probability 1/6. Two initial failures return to the same odd-index situation, with probability (5/6)². A failure followed by a six contributes zero.',r'Thus p=1/6+(25/36)p, giving p=6/11.'],['Group the first two rolls into cases.','Two failures restore the original parity of the waiting problem.'],'Use a renewal equation for an unbounded process.',lambda:S.solve(S.Eq(S.Symbol('p'),S.Rational(1,6)+S.Rational(25,36)*S.Symbol('p')),S.Symbol('p'))[0],'Independent geometric series sum with first term 1/6 and ratio 25/36.'),
q(5,r'A fair coin is tossed until two consecutive heads first appear. What is the expected number of tosses?',6,[(4,'Take the reciprocal of P(HH)=1/4 but count two-toss blocks as single tosses.'),(2,'Use the reciprocal probability of a head.'),(8,'Ignore overlap and reset after every pair.'),(3,'Omit the cost of failed returns to the initial state.')],[r'Let E0 be the expected remaining tosses with no trailing head, and E1 after one trailing head.',r'First-step analysis gives $E_0=1+(E_0+E_1)/2$ and $E_1=1+E_0/2$; a head from state one finishes.',r'Solving gives E0=6. Remembering only total heads would lose the consecutive-pattern information.'],['Record whether the most recent toss was a head.','Write expected remaining time after one additional toss in each state.'],'Choose sufficient memory for an overlapping target pattern.',lambda:S.solve([S.Eq(S.Symbol('a'),1+(S.Symbol('a')+S.Symbol('b'))/2),S.Eq(S.Symbol('b'),1+S.Symbol('a')/2)],[S.Symbol('a'),S.Symbol('b')])[S.Symbol('a')],'Exact absorbing-state linear system.'),
q(6,r'Urn A has 3 red and 2 blue balls; urn B has 1 red and 4 blue balls. One random ball is moved from A to B, then one is drawn from B. What is the probability the drawn ball is red?',F(4,15),[(F(1,5),'Ignore the transfer.'),(F(3,5),'Use the source urn’s red probability.'),(F(1,3),'Assume the transferred ball is certainly red.'),(F(1,6),'Assume the transferred ball is certainly blue.')],[r'A red transfer occurs with probability 3/5 and makes the final red probability 2/6.',r'A blue transfer occurs with probability 2/5 and makes it 1/6.',r'The total is (3/5)(2/6)+(2/5)(1/6)=4/15.'],['Condition on the transferred ball’s color.','The second urn contains six balls after either transfer.'],'Partition a dependent experiment into conditional branches.',lambda:F(sum(color=='R' for transfer in 'RRRBB' for color in 'RBBBB'+transfer),30),'Independent enumeration of transfer/draw pairs.'),
q(7,r'A permutation of five distinct objects is chosen uniformly. What is the expected number of objects remaining in their original positions?',1,[(0,'Round each position’s expectation down to zero before adding.'),(F(1,5),'Report the probability for one specified object.'),(5,'Assume every object stays fixed.'),(F(5,2),'Assume each object has probability one-half of staying fixed.')],[r'For each position i, let I_i indicate whether it is fixed.',r'Each object is equally likely to occupy any of five positions, so E[I_i]=1/5.',r'Linearity gives E[I_1+...+I_5]=5·(1/5)=1. Independence is not needed.'],['Express the total as a sum of five indicator variables.','Linearity of expectation does not require the indicators to be independent.'],'Use indicator expectation despite dependent events.',lambda:F(sum(sum(i==t[i] for i in range(5)) for t in permutations(range(5))),120)),
q(8,r'A point (x,y) is chosen uniformly from the unit square. What is the probability that x≥1/4 and x+y≤1?',F(9,32),[(F(3,8),'Multiply two probabilities for dependent conditions.'),(F(1,2),'Ignore the vertical cutoff.'),(F(9,16),'Forget the triangular area factor.'),(F(7,32),'Report part of the excluded region.')],[r'The favorable region is the right triangle with vertices (1/4,0),(1,0),(1/4,3/4).',r'Its perpendicular legs both have length 3/4, so its area is (1/2)(3/4)²=9/32.',r'The unit square has area one, making this area the probability.'],['Draw both inequalities in the same square.','The favorable event is their intersection, not a product of separate areas.'],'Model dependent continuous conditions as an area intersection.',lambda:S.Polygon(S.Point(F(1,4),0),S.Point(1,0),S.Point(F(1,4),F(3,4))).area,'Independent polygon area.'),
q(9,r'Two points are chosen independently and uniformly by angle on a circle of radius R. What is the probability that their chord is longer than $\sqrt3R$?',F(1,3),[(F(1,2),'Use a different random-chord sampling rule.'),(F(2,3),'Count the complementary angular region.'),(F(1,4),'Use an area-uniform midpoint model.'),(F(3,4),'Confuse the radius fraction with a probability.')],[r'By rotational symmetry fix the first endpoint at angle zero; the other angle is uniform from 0 to 2π.',r'The chord exceeds √3R precisely when its minor central angle exceeds 2π/3, so the second angle lies between 2π/3 and 4π/3.',r'The favorable angular interval has length 2π/3 out of 2π, giving 1/3. The endpoint sampling rule is essential.'],['Fix one endpoint using rotational symmetry.','Translate chord length into a central-angle interval.'],'Respect the specified random model in a geometric probability problem.',lambda:S.Rational(2,3)/2,'Exact angular measure ratio.'),
q(10,r'Nine distinct balls are independently placed into three labeled boxes, each equally likely. What is the probability that every box contains an odd number of balls?',F(1640,6561),[(F(1,4),'Assume parity patterns are exactly equally likely after finitely many balls.'),(F(1,8),'Treat the three parity events as independent.'),(F(4920,6561),'Forget the last division by three in the state update.'),(F(182,729),'Stop after seven balls.')],[r'After an odd number of balls, the number of odd boxes is one or three. Let b_n be the probability it is three.',r'Over two more balls, a one-odd state becomes three-odd with probability 2/9, while a three-odd state returns to three-odd with probability 1/3. Thus $b_{n+2}=2/9+b_n/9$.',r'Starting b_1=0 gives b_3=2/9, b_5=20/81, b_7=182/729, and b_9=1640/6561. Tracking parity makes box occupancies unnecessary.'],['Track the number of boxes with odd occupancy, not all occupancy triples.','Two placements preserve the odd-time state types and give a small recurrence.'],'Compress a large probability space into parity states.',lambda:F(sum(all(t.count(k)%2 for k in range(3)) for t in product(range(3),repeat=9)),3**9),'Independent enumeration of all 19,683 assignments.'),
q(11,r'A fair three-sided spinner has outcomes A,B,C. What is the expected number of spins needed to see all three outcomes?',F(11,2),[(3,'Assume every spin shows a new outcome.'),(6,'Use a constant success probability one-half.'),(9,'Use probability one-third for every stage.'),(F(9,2),'Omit the first guaranteed new outcome.')],[r'The waiting time for the first distinct outcome is one spin.',r'After one is known, a new outcome has probability 2/3, so its expected waiting time is 3/2. For the final missing outcome it is 3.',r'Add the stage expectations: 1+3/2+3=11/2. Independence between stages is not required for this addition.'],['Separate the process by how many distinct outcomes have been collected.','At each stage the chance of a new outcome is constant until success.'],'Decompose collection time into geometric waiting stages.',lambda:1+S.Rational(3,2)+3,'Independent state equations E2=1+(2/3)E2 and E1=1+(1/3)E1+(2/3)E2.'),
q(12,r'A wins each independent game against B with probability 2/3. They play until someone wins two games. What is the probability A wins the match?',F(20,27),[(F(4,9),'Count only a two-game sweep.'),(F(8,27),'Require A to win three games.'),(F(2,3),'Assume the match probability equals the single-game probability.'),(F(22,27),'Include LLW as an A victory, even though B has already won after LL.')],[r'A can win by WW, WLW, or LWW.',r'The probabilities are p²,p²(1-p),p²(1-p), with p=2/3.',r'The sum is 4/9+8/27=20/27. Stopped histories cannot be extended and counted again.'],['List terminal histories, stopping as soon as someone gets two wins.','The final game of a three-game A victory must be a win.'],'Count absorbing histories without extending completed processes.',lambda:S.Rational(2,3)**2*(3-2*S.Rational(2,3)),'Independent best-of-three binomial probability.'),
q(13,r'One of two urns is chosen with equal probability. Urn A has 3 red and 1 blue ball; urn B has 1 red and 3 blue balls. A drawn ball is red. What is the probability urn A was chosen?',F(3,4),[(F(1,2),'Ignore the information supplied by the red draw.'),(F(3,8),'Report the joint probability rather than the conditional probability.'),(F(1,4),'Report the posterior for urn B.'),(1,'Assume a red ball identifies its source with certainty.')],[r'The joint probabilities of choosing A and red, or B and red, are 3/8 and 1/8.',r'The total red probability is 1/2.',r'The desired conditional probability is (3/8)/(1/2)=3/4.'],['Compute the two ways the observed red event could happen.','Normalize the A-and-red branch by the total probability of red.'],'Reverse conditioning through joint probabilities.',lambda:F(3,3+1),'Independent equally weighted urn-slot enumeration.',2),
q(14,r'Two points are chosen independently and uniformly on a unit-length stick and used as cuts. What is the probability that the three pieces form a nondegenerate triangle?',F(1,4),[(F(1,2),'Require only that the cuts lie in opposite halves.'),(F(1,8),'Count only one ordering of the two labeled cuts.'),(F(3,4),'Report the complementary failure probability.'),(F(1,3),'Assume all possible longest-piece labels imply equal success fractions.')],[r'The pieces form a triangle exactly when each has length less than one half.',r'For ordered cuts u<v, this requires u<1/2, v>1/2, and v-u<1/2. In the unit square of labeled cut positions, one ordering gives a triangle of area 1/8.',r'The opposite ordering gives another disjoint triangle of area 1/8, totaling 1/4. Boundary events have probability zero.'],['Use the triangle inequality on the largest piece.','Draw the allowed region for the two cut positions and account for both orders.'],'Convert a geometric feasibility condition into a planar probability region.',lambda:2*S.Polygon(S.Point(0,F(1,2)),S.Point(F(1,2),F(1,2)),S.Point(F(1,2),1)).area,'Independent exact favorable-region area.')]
e=[
q(101,r'A fair coin is tossed until the pattern HT first appears in consecutive tosses. What is the expected number of tosses?',4,[(2,'Count only the pattern length.'),(6,'Use the waiting time for HH, which has different overlap behavior.'),(8,'Treat nonoverlapping pairs as independent trials.'),(3,'Ignore one possible repeated-head delay.')],[r'Let E0 be the remaining expectation before a trailing H is available, and E1 after a trailing H.',r'From state one, a tail finishes and a head leaves a trailing H, so $E_1=1+E_1/2$ and $E_1=2$.',r'From state zero, a tail stays there and a head enters state one: $E_0=1+(E_0+E_1)/2$, giving $E_0=4$.',r'Contrast HH: after a tail from the one-head state, the process loses its partial progress. The different transition, not the pattern length, changes the expectation.'],['Keep only the suffix that could start the target pattern.','A head after a head still leaves useful partial progress for HT.'],'Choose pattern states and explain their transitions.',lambda:S.solve([S.Eq(S.Symbol('a'),1+(S.Symbol('a')+S.Symbol('b'))/2),S.Eq(S.Symbol('b'),1+S.Symbol('b')/2)],[S.Symbol('a'),S.Symbol('b')])[S.Symbol('a')],'Exact first-step state equations.'),
q(102,r'A bag contains 4 red and 3 blue balls. Two are drawn without replacement. Given that their colors differ, what is the probability the first is red?',F(1,2),[(F(4,7),'Ignore the condition on the second color.'),(F(2,7),'Report the joint red-blue probability.'),(F(3,7),'Use the initial blue proportion.'),(F(2,3),'Normalize by an unrelated color count.')],[r'The probabilities of the two retained ordered color histories are P(RB)=(4/7)(3/6)=2/7 and P(BR)=(3/7)(4/6)=2/7.',r'The event of different colors has probability 4/7.',r'The conditional probability is (2/7)/(4/7)=1/2.',r'The equality follows from reversing the order of a red-blue pair; it does not require the bag to contain equal numbers of the two colors.'],['Condition on the two possible ordered color histories.','Compare their joint probabilities before normalizing.'],'Use a conditional symmetry with unequal initial proportions.',lambda:F(4*3,4*3+3*4),'Independent ordered distinct-ball pairing.',2)]
p[0]['family']='probability-states-q01'
finish('probability-states','Probability: conditioning, states & expectation','Probability','conditional expectation recurrence constrained-counting',11,'124–167',
 [r'A probability calculation is only as sound as its sample space. Conditions can change which outcomes are retained, and repeated processes can require memory of a partial pattern. The productive move is often to replace a large history by a small state that retains exactly what affects the future.',r'The textbook’s probability-state chapter motivates this approach. Here the state choices are derived explicitly, and finite models are checked by enumeration rather than relying on a plausible-looking fraction.'],
 [section('Condition on the information actually given',r'For a uniform finite experiment, conditional probability can be found by counting favorable outcomes inside the conditioned event. The original denominator is no longer appropriate. Ordered dice or coin strings remain distinct even when the event is described only by a sum or a number of heads.',r'For a transfer or source-selection experiment, partition into disjoint branches and multiply conditional probabilities along each branch. Add the branches that produce the target event. If the question reverses the information, normalize the relevant joint probability by the total probability of the observed event.',r'Color patterns are not automatically equally likely when an urn has unequal color counts. Count subsets or ordered selections of distinct balls, or use the correct sequential probabilities. Numerator and denominator must use the same ordering convention.'),
 section('Choose a sufficient state',r'A state should retain everything that changes the distribution of the next step and discard irrelevant history. For consecutive-head targets, whether the last toss was a head matters; the total number of earlier heads does not. For occupancy parity, actual box counts can be discarded once the parities are known.',r'Write each transition before solving a recurrence. A two-step update can be simpler than a one-step update when parity alternates the available state types. In the odd-occupancy problem, only one or three boxes can be odd after an odd number of placements, giving a two-state recurrence.',r'For waiting times, first-step analysis adds one for the next trial and then averages the remaining expectations in the successor states. An absorbing successor contributes zero remaining time. Overlapping patterns require care: a new symbol may preserve partial progress, erase it, or complete the target.'),
 section('Separate probability, expectation, and geometry',r'Expected counts can be written as sums of indicators. Linearity of expectation requires no independence, so fixed positions in a random permutation can be counted one at a time even though their events are dependent. An expected value need not be the most probable count or even an attainable count.',r'Collection times can be split into stages with geometric waiting times. At a stage with success probability p, the equation E=1+(1-p)E gives E=1/p. Add the stage expectations after identifying how the success probability changes.',r'For uniform continuous sampling, probability is a length or area ratio in the specified sample space. Random endpoints, random midpoints, and random lines produce different random-chord models. For cut sticks or intersecting inequalities, draw the joint region rather than multiplying dependent one-dimensional probabilities. Boundary cases of zero area can be excluded for a strict triangle condition without changing the probability.')],
 ['Construct the correct conditional sample space.','Compress repeated experiments into sufficient states and solve their recurrences.','Use indicator expectations and explicitly specified geometric sampling models.'],
 [r'Partition an observed event into disjoint joint-probability branches before normalizing.',r'Write $E_s=1+\sum_t p_{st}E_t$, with zero remaining time in an absorbing state.',r'Write a count as a sum of indicators and apply expectation linearly.'],
 'Independence is a property to establish, not a default. Conditioning, sampling without replacement, and competing occupancy parities usually introduce dependence.',e,p,
 dict(prompt=r'For waiting until HH, complete $E_0=1+(E_0+E_1)/2$ and $E_1=1+\square$. Explain the missing term.',answer=r'The missing term is $E_0/2$.',steps=[r'A head from the one-head state completes the target and leaves zero remaining tosses.',r'A tail occurs with probability one-half and returns to the no-trailing-head state. Solving then gives E0=6.']),
 ['conditional normalization','parity-state compression','pattern waiting times','indicator expectation'],
 [(r'P(A\mid B)=P(A\cap B)/P(B)','Conditional probability','updating a probability after restricting to an observed event','$P(B)>0$; the conditioned sample space is $B$.'),(r'P(A)=\sum_iP(B_i)P(A\mid B_i)','Total probability','combining disjoint conditional branches of an experiment','The $B_i$ form a partition, and branches with zero probability contribute zero.'),(r'E_s=1+\sum_t p_{st}E_t','First-step waiting equation','finding expected remaining trials from a sufficient state','One trial is counted now; absorbing states have zero remaining expectation and the expected absorption time is finite.'),(r'\mathbb E[\sum_i I_i]=\sum_iP(I_i=1)','Indicator expectation','finding an expected count without its full distribution','The $I_i$ are indicator variables; independence is not required.')], 'probability-states')

