p[9]['source']=dict(kind='adapted',title='Adapted from 2023 AMC 10B, Problem 21',url='https://live.poshenloh.com/past-contests/amc10/2023B/problem/21',attribution='Changes: nine balls, exact probability, and a two-step parity-state derivation. The released large-n estimation problem remains linked separately.')
